// Instructions describe the web application. Example people and amounts are fictitious.
// Keep navigation paths and button names aligned with the sources on every product change.
const all: HelpAudience[] = ['verwaltung', 'mitarbeitende', 'klienten'];
const office: HelpAudience[] = ['verwaltung'];
const team: HelpAudience[] = ['verwaltung', 'mitarbeitende'];
const clients: HelpAudience[] = ['verwaltung', 'klienten'];
function article(
  id: string, category: HelpCategoryId, title: string, summary: string,
  audiences: HelpAudience[], location: string[], route: string | undefined,
  prerequisites: string[], steps: [string, string][], example: [string, string],
  checks: string[], troubleshooting: [string, string][], related: string[], sources: string[], keywords: string[] = [],
): HelpArticle {
  return { id, category, title, summary, audiences, location, route, prerequisites,
    steps: steps.map(([title, text]) => ({ title, text })), example: { title: example[0], text: example[1] },
    checks, troubleshooting: troubleshooting.map(([problem, solution]) => ({ problem, solution })), related, sources, keywords };
}

